<?php
require_once __DIR__ . '/../implements/conexion.php';
function buscarLibros(string $busqueda='', string $estado=''): array { global $pdo; $sql='SELECT * FROM libros WHERE (titulo LIKE ? OR autor LIKE ? OR categoria LIKE ?)'; $like='%'.$busqueda.'%'; $args=[$like,$like,$like]; if(in_array($estado,['Disponible','Prestado'],true)){$sql.=' AND estado=?';$args[]=$estado;} $sql.=' ORDER BY id_libro DESC';$s=$pdo->prepare($sql);$s->execute($args);return $s->fetchAll(); }
function obtenerEstadisticasBiblioteca(): array { global $pdo; return ['libros'=>(int)$pdo->query('SELECT COUNT(*) FROM libros')->fetchColumn(),'disponibles'=>(int)$pdo->query("SELECT COUNT(*) FROM libros WHERE estado='Disponible'")->fetchColumn(),'prestados'=>(int)$pdo->query("SELECT COUNT(*) FROM libros WHERE estado='Prestado'")->fetchColumn(),'atrasos'=>(int)$pdo->query("SELECT COUNT(*) FROM prestamos WHERE estado_prestamo='Activo' AND fecha_devolucion<CURDATE()")->fetchColumn(),'usuarios'=>(int)$pdo->query("SELECT COUNT(*) FROM usuarios WHERE rol='Usuario'")->fetchColumn()]; }
